import { useState } from "react";

export function SelectedState({
  item1 = "{{item1}}",
  item2 = "{{item2}}",
  item3 = "{{item3}}",
  accent = "{{accent}}",
  force = {{force}},
}) {
  const [selected, setSelected] = useState(force ? 1 : -1);
  const items = [item1, item2, item3];
  return (
    <div>
      <div style={{ display: "flex", gap: 8, width: 300, boxSizing: "border-box", font: "14px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 16, borderRadius: 12 }}>
        {items.map((item, i) => (
          <label key={item} style={{ flex: 1, textAlign: "center", padding: "10px 6px", borderRadius: 8, border: `1.5px solid ${selected === i ? accent : "#24143025"}`, background: selected === i ? accent : "transparent", fontWeight: 600, fontSize: 13, cursor: "pointer", position: "relative" }}>
            <input type="radio" checked={selected === i} onChange={() => setSelected(i)} style={{ position: "absolute", opacity: 0, inset: 0, margin: 0, cursor: "pointer" }} />
            {item}
          </label>
        ))}
      </div>
      <p style={{ width: 300, margin: "8px 0 0", fontSize: 11, color: "#241430888" }}>Real radio inputs styled as chips — click any chip to select it.</p>
    </div>
  );
}
